import { DISPOSABLE_DOMAINS_TEXT } from "../data/disposable-domains";
import { getSetting, OWNER_TENANT, setSetting } from "./db";

/**
 * Throw-away inbox services: an address there cannot back a free plan (a new one costs nothing to make).
 * The big list (data/disposable-domains.ts, ~13k domains incl. temp-mail.org's rotating ones) is regenerated by
 * scripts/update-disposable-domains.mjs; these well-known ones are always included.
 */
const KNOWN = [
  "mailinator.com", "mailinator.net", "guerrillamail.com", "guerrillamail.net", "guerrillamail.org", "guerrillamailblock.com", "sharklasers.com",
  "grr.la", "10minutemail.com", "10minutemail.net", "temp-mail.org", "temp-mail.io", "tempmail.com", "tempmail.net", "tempmailo.com", "tempmail.plus",
  "tempr.email", "throwawaymail.com", "yopmail.com", "yopmail.net", "yopmail.fr", "trashmail.com", "trashmail.de", "getnada.com", "nada.email",
  "dispostable.com", "maildrop.cc", "mailnesia.com", "mintemail.com", "mohmal.com", "emailondeck.com", "fakeinbox.com", "spamgourmet.com",
  "mailcatch.com", "moakt.com", "burnermail.io", "1secmail.com", "1secmail.net", "1secmail.org", "dropmail.me", "emailfake.com", "fakemail.net",
  "inboxkitten.com", "mail.tm", "mailpoof.com", "tmail.ws", "tmpmail.org", "tmpmail.net", "minuteinbox.com", "spambox.us", "mytemp.email",
];

let domains: Set<string> | null = null;
const all = () => (domains ??= new Set([...KNOWN, ...DISPOSABLE_DOMAINS_TEXT.split("\n")]));

export function isDisposableEmail(email: string | null | undefined): boolean {
  const domain = (email ?? "").split("@")[1]?.trim().toLowerCase();
  if (!domain) return false;
  // Sub-domains of a listed service count too (e.g. x.mailinator.com).
  const set = all();
  const parts = domain.split(".");
  for (let i = 0; i < parts.length - 1; i++) if (set.has(parts.slice(i).join("."))) return true;
  return false;
}

/** Domains the lists added after this build (refreshed daily), cached per worker for an hour. */
let extra: { at: number; set: Set<string> } | null = null;
const EXTRA_KEY = "disposable_domains_extra";

async function extraDomains(db: D1Database): Promise<Set<string>> {
  if (extra && Date.now() - extra.at < 3_600_000) return extra.set;
  const v = await getSetting<string[]>(db, OWNER_TENANT, EXTRA_KEY, []).catch(() => [] as string[]);
  extra = { at: Date.now(), set: new Set(v) };
  return extra.set;
}

/** isDisposableEmail plus the domains the daily refresh found since this build. */
export async function isDisposable(db: D1Database, email: string | null | undefined): Promise<boolean> {
  if (isDisposableEmail(email)) return true;
  const domain = (email ?? "").split("@")[1]?.trim().toLowerCase();
  if (!domain) return false;
  const set = await extraDomains(db);
  const parts = domain.split(".");
  for (let i = 0; i < parts.length - 1; i++) if (set.has(parts.slice(i).join("."))) return true;
  return false;
}

const SOURCES = [
  "https://raw.githubusercontent.com/disposable-email-domains/disposable-email-domains/main/disposable_email_blocklist.conf",
  "https://raw.githubusercontent.com/7c/fakefilter/main/txt/data.txt",
];
const NEVER = new Set(["gmail.com", "googlemail.com", "outlook.com", "hotmail.com", "live.com", "msn.com", "yahoo.com", "icloud.com", "me.com", "proton.me", "protonmail.com", "aol.com", "gmx.com", "zoho.com", "yandex.com", "mail.ru"]);

/**
 * Daily: re-reads the two public lists (temp-mail services open new domains every day) and keeps the domains
 * this build does not know yet. Two small downloads a day; a failed one keeps the previous result.
 */
export async function refreshDisposableDomains(db: D1Database, fetcher: typeof fetch = fetch): Promise<number> {
  const known = all();
  const found = new Set<string>();
  for (const url of SOURCES) {
    const r = await fetcher(url, { headers: { "User-Agent": "shayyek-disposable-refresh" } });
    if (!r.ok) throw new Error(`${url}: HTTP ${r.status}`);
    for (const line of (await r.text()).split("\n")) {
      const d = line.trim().toLowerCase();
      if (d && !d.startsWith("#") && /^[a-z0-9.-]+\.[a-z]{2,}$/.test(d) && !NEVER.has(d) && !known.has(d)) found.add(d);
    }
  }
  const list = [...found].sort().slice(0, 50_000);
  await setSetting(db, OWNER_TENANT, EXTRA_KEY, list);
  extra = { at: Date.now(), set: new Set(list) };
  return list.length;
}
